package com.nook.widgets;

import android.Manifest;
import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.hardware.*;
import android.media.*;
import android.net.Uri;
import android.os.*;
import android.provider.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.time.LocalDate;

/** Foreground, user-initiated data connections, measurements and capture. */
public final class ExtraActivity extends Activity implements SensorEventListener {
    private static volatile boolean recordingNow;
    public static boolean recordingActive(){return recordingNow;}
    private int widgetId;private String kind,provider,op;private JSONObject root,settings;private SensorManager sensors;private float heading=Float.NaN;private TextView headline,detail;private final Handler handler=new Handler(Looper.getMainLooper());private MediaRecorder recorder;private MediaPlayer player;private File recording;private long started;private JSONArray amplitudes=new JSONArray();
    @Override public void onCreate(Bundle saved){super.onCreate(saved);widgetId=getIntent().getIntExtra("widget",-1);op=getIntent().getStringExtra("op");kind=getIntent().getStringExtra("module");if(op==null)op="open";AppWidgetProviderInfo info=AppWidgetManager.getInstance(this).getAppWidgetInfo(widgetId);if(info==null){finish();return;}provider=Widgets.kindOf(info.provider);root=Store.config(this,widgetId);String actual=provider.equals("universal")?UniversalWidget.currentPage(root):provider;if(!actual.equals(kind)||ExtraKinds.index(kind)<0){finish();return;}settings=provider.equals("universal")?UniversalWidget.pageSettings(root,kind):root;
        if(kind.equals("compass")){compass();return;}if(kind.equals("recorder")){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},71);else recorder();return;}if(kind.equals("breathing")){breathing();return;}if(kind.equals("tracker")){tracker();return;}
        if(kind.equals("screentime")){try{startActivityForResult(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS),72);}catch(ActivityNotFoundException e){unavailable("Usage-access settings are unavailable on this device.");}return;}if(kind.equals("devicecare")){Widgets.update(this,widgetId,provider);launch(new Intent(Settings.ACTION_INTERNAL_STORAGE_SETTINGS));return;}
        if(kind.equals("translate")){translate();return;}
        if(kind.equals("news")||kind.equals("stocks")){if(op.equals("refresh")){if(!FeedData.configured(kind,settings)){configure();return;}screen("Refreshing…","Connecting to your selected source.");new Thread(()->{FeedData.refresh(getApplicationContext(),kind,settings);Widgets.updateAll(getApplicationContext());runOnUiThread(()->{if(!isFinishing())finish();});},"Nook source refresh").start();}else if(op.equals("story")){web(getIntent().getStringExtra("value"));}else web(kind.equals("stocks")?"https://www.alphavantage.co/documentation/":settings.optString("feedUrl"));return;}
        int slot;try{slot=Integer.parseInt(getIntent().getStringExtra("value"));}catch(Exception e){slot=0;}slot=Math.max(0,Math.min(2,slot));
        if(kind.equals("files")){String uri=settings.optString("file"+slot,"");if(uri.isEmpty()){configure();return;}Uri document=Uri.parse(uri);String mime;try{mime=getContentResolver().getType(document);}catch(SecurityException e){unavailable("Access to this file has expired. Choose it again in widget options.");return;}launch(new Intent(Intent.ACTION_VIEW).setDataAndType(document,mime==null?"*/*":mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));return;}
        if(kind.equals("bookmarks")){web(settings.optString("url"+slot));return;}if(kind.equals("maps")){web("https://www.google.com/maps/dir/?api=1&destination="+Uri.encode(settings.optString("destination"+slot)));return;}
        if(kind.equals("shortcuts")||kind.equals("service")){Intent app=getPackageManager().getLaunchIntentForPackage(settings.optString("package"+slot));if(app==null){unavailable("Choose an installed app in widget options.");return;}launch(app);return;}configure();
    }
    private LinearLayout screen(String title,String text){LinearLayout panel=Ui.column(this);panel.setBackgroundColor(Ui.BG);Ui.pad(panel,24,26);setContentView(panel);Ui.insets(this,panel);panel.addView(Ui.iconButton(this,"back","Go back",this::finish));Ui.gap(panel,24);headline=Ui.bold(this,title,36,Ui.TEXT);panel.addView(headline);Ui.gap(panel,14);detail=Ui.text(this,text,15,Ui.MUTED);panel.addView(detail);Ui.gap(panel,24);return panel;}
    private void configure(){startActivity(new Intent(this,WidgetConfigActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId));finish();}
    private void save(){Store.config(this,widgetId,root);Widgets.update(this,widgetId,provider);}
    private void unavailable(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();finish();}
    private void launch(Intent intent){try{startActivity(intent);finish();}catch(ActivityNotFoundException|SecurityException e){unavailable("No compatible app is available.");}}
    private void web(String address){if(!FeedData.safeUrl(address)){unavailable("Choose a valid web address in widget options.");return;}launch(new Intent(Intent.ACTION_VIEW,Uri.parse(address)));}
    private void tracker(){LinearLayout panel=screen(ExtraData.trackerName(settings),"Your own record. This does not sync private health accounts.");EditText[] fields=new EditText[3];for(int n=0;n<3;n++){panel.addView(Ui.text(this,"Recorded amount "+(n+1),12,Ui.MUTED));fields[n]=new EditText(this);fields[n].setTextColor(Ui.TEXT);fields[n].setInputType(android.text.InputType.TYPE_CLASS_NUMBER);fields[n].setText(String.valueOf(ExtraData.trackerValue(settings,n)));panel.addView(fields[n]);}panel.addView(Ui.button(this,"Save record",Ui.ACCENT,Ui.BG,()->{for(int n=0;n<3;n++){try{ExtraData.put(settings,"amount"+n,Math.max(0,Math.min(1000000,Integer.parseInt(fields[n].getText().toString()))));}catch(Exception e){fields[n].setError("Enter a whole number");return;}}ExtraData.put(settings,"trackedDay",LocalDate.now().toString());save();finish();}));}
    private void translate(){if(op.equals("web")){web("https://translate.google.com/");return;}LinearLayout panel=screen("Translate text","Your text is sent to Google Translate only when you choose Translate.");EditText input=new EditText(this);input.setTextColor(Ui.TEXT);input.setHintTextColor(Ui.MUTED);input.setHint("Text to translate");panel.addView(input);panel.addView(Ui.button(this,"Translate",Ui.ACCENT,Ui.BG,()->{String text=input.getText().toString().trim();if(text.isEmpty()){input.setError("Enter some text");return;}String language=settings.optString("language","en");if(!language.matches("[A-Za-z-]{2,12}"))language="en";web("https://translate.google.com/?sl=auto&tl="+language+"&text="+Uri.encode(text)+"&op=translate");}));}
    private void compass(){LinearLayout panel=screen("Compass","Magnetic heading. Keep your phone level; move away from magnetic interference.");panel.addView(Ui.button(this,"Save reading and close",Ui.ACCENT,Ui.BG,this::finish));sensors=getSystemService(SensorManager.class);Sensor sensor=sensors.getDefaultSensor(Sensor.TYPE_ROTATION_VECTOR);if(sensor==null){detail.setText("This device does not expose a compatible orientation sensor.");return;}sensors.registerListener(this,sensor,SensorManager.SENSOR_DELAY_UI);}
    @Override public void onSensorChanged(SensorEvent event){float[] matrix=new float[9],remapped=new float[9],orientation=new float[3];SensorManager.getRotationMatrixFromVector(matrix,event.values);int rotation=getWindowManager().getDefaultDisplay().getRotation(),x=SensorManager.AXIS_X,y=SensorManager.AXIS_Y;if(rotation==Surface.ROTATION_90){x=SensorManager.AXIS_Y;y=SensorManager.AXIS_MINUS_X;}else if(rotation==Surface.ROTATION_180){x=SensorManager.AXIS_MINUS_X;y=SensorManager.AXIS_MINUS_Y;}else if(rotation==Surface.ROTATION_270){x=SensorManager.AXIS_MINUS_Y;y=SensorManager.AXIS_X;}SensorManager.remapCoordinateSystem(matrix,x,y,remapped);SensorManager.getOrientation(remapped,orientation);heading=(float)((Math.toDegrees(orientation[0])+360)%360);headline.setText(Math.round(heading)+"°");detail.setText(new String[]{"North","North-east","East","South-east","South","South-west","West","North-west"}[Math.round(heading/45)%8]+" · magnetic heading");}
    @Override public void onAccuracyChanged(Sensor sensor,int accuracy){}
    private void breathing(){LinearLayout panel=screen("Ready to breathe","This session ends when you leave the screen.");panel.addView(Ui.button(this,"End session",Ui.ACCENT,Ui.BG,this::finish));int variant=WidgetDesign.clamp(settings.optInt("variant",0),0,2);int[] seconds=variant==0?new int[]{4,4,4,4}:variant==1?new int[]{4,7,8,0}:new int[]{5,0,5,0};String[] labels={"Breathe in","Hold","Breathe out","Rest"};long begin=SystemClock.elapsedRealtime();handler.post(new Runnable(){public void run(){int cycle=seconds[0]+seconds[1]+seconds[2]+seconds[3],position=(int)((SystemClock.elapsedRealtime()-begin)/1000%cycle),phase=0;while(phase<3&&position>=seconds[phase]){position-=seconds[phase];phase++;}headline.setText(labels[phase]);detail.setText((seconds[phase]-position)+" seconds · follow a comfortable rhythm");handler.postDelayed(this,250);}});}
    private void recorder(){LinearLayout panel=screen("Voice memos","Recording stops and saves when you leave this screen. Audio stays in this app's private storage.");panel.addView(Ui.button(this,"Record",Ui.ACCENT,Ui.BG,this::startRecording));panel.addView(Ui.button(this,"Stop and save",Ui.SURFACE,Ui.ACCENT,this::stopRecording));panel.addView(Ui.button(this,"Play last memo",Ui.SURFACE,Ui.ACCENT,this::play));panel.addView(Ui.button(this,"Close",Ui.SURFACE,Ui.MUTED,this::finish));if(op.equals("record"))startRecording();else if(op.equals("play"))play();}
    private void startRecording(){if(recorder!=null)return;releasePlayer();try{recording=new File(getFilesDir(),"memo-"+System.currentTimeMillis()+".m4a");recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setOutputFile(recording.getAbsolutePath());recorder.prepare();recorder.start();recordingNow=true;started=SystemClock.elapsedRealtime();amplitudes=new JSONArray();getSharedPreferences("nook_recorder",0).edit().putBoolean("recording",true).commit();headline.setText("Recording…");Widgets.updateAll(this);handler.post(new Runnable(){public void run(){if(recorder==null)return;detail.setText(ExtraData.stopwatchText(SystemClock.elapsedRealtime()-started)+" · microphone active");try{if(amplitudes.length()<120)amplitudes.put(recorder.getMaxAmplitude());}catch(Exception ignored){}handler.postDelayed(this,500);}});}catch(Exception e){if(recorder!=null){recorder.release();recorder=null;recordingNow=false;}getSharedPreferences("nook_recorder",0).edit().putBoolean("recording",false).commit();headline.setText("Microphone unavailable");detail.setText("Check microphone access and whether another app is recording.");}}
    private void stopRecording(){if(recorder==null)return;boolean saved=false;long duration=SystemClock.elapsedRealtime()-started;try{recorder.stop();saved=true;}catch(RuntimeException ignored){}finally{recorder.release();recorder=null;recordingNow=false;handler.removeCallbacksAndMessages(null);}android.content.SharedPreferences.Editor edit=getSharedPreferences("nook_recorder",0).edit().putBoolean("recording",false);if(saved)edit.putString("lastFile",recording.getAbsolutePath()).putLong("duration",duration).putString("wave",amplitudes.toString());else if(recording!=null)recording.delete();edit.commit();headline.setText(saved?"Memo saved":"Recording was too short");Widgets.updateAll(this);}
    private void play(){stopRecording();releasePlayer();String path=getSharedPreferences("nook_recorder",0).getString("lastFile","");try{File file=new File(path);if(!file.getCanonicalFile().getParentFile().equals(getFilesDir().getCanonicalFile())||!file.isFile())throw new IOException();player=new MediaPlayer();player.setDataSource(file.getAbsolutePath());player.prepare();player.start();headline.setText("Playing your memo");player.setOnCompletionListener(p->{releasePlayer();headline.setText("Voice memos");});}catch(Exception e){headline.setText("No saved memo yet");}}
    private void releasePlayer(){if(player!=null){player.release();player=null;}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==72){Widgets.updateAll(this);finish();}}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==71&&grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)recorder();else unavailable("Microphone access is needed only to record voice memos.");}
    @Override protected void onStop(){if(sensors!=null)sensors.unregisterListener(this);if(!Float.isNaN(heading)){getSharedPreferences("nook_sensors",0).edit().putFloat("heading",heading).putLong("measuredAt",System.currentTimeMillis()).commit();Widgets.updateAll(this);}stopRecording();releasePlayer();handler.removeCallbacksAndMessages(null);super.onStop();}
}
